<template><div><div class="page-head"><div><h1>{{editing?'Edit product':'New product'}}</h1><p class="muted">Product information, media, pricing and inventory.</p></div><div class="head-actions"><button class="btn secondary" @click="router.back()">Cancel</button><button class="btn" @click="save">Save product</button></div></div><div class="editor"><section class="card form-card"><div class="tabs"><button v-for="t in tabs" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><div v-if="tab==='Basic info'" class="form"><label>Product name<input v-model="form.name" class="input"/></label><label>SKU<input v-model="form.sku" class="input"/></label><label>Category<select v-model="form.category" class="select"><option>Lighting</option><option>Protection</option><option>Switchgear</option><option>Meters</option></select></label><label>Description<textarea v-model="form.description" class="input" rows="6"></textarea></label></div><div v-else-if="tab==='Media'" class="media-box"><div class="upload">Drop product images here<br/><span>PNG, JPG up to 5MB</span></div></div><div v-else class="form two"><label>Price<input v-model.number="form.price" type="number" class="input"/></label><label>Compare at price<input v-model.number="form.compareAtPrice" type="number" class="input"/></label><label>Stock<input v-model.number="form.stock" type="number" class="input"/></label><label>Status<select v-model="form.status" class="select"><option>Published</option><option>Draft</option></select></label></div></section><aside class="card preview"><div class="eyebrow">Preview</div><div class="preview-image"></div><h3>{{form.name||'Product name'}}</h3><p class="muted">{{format(form.price)}} EGP · {{form.stock}} in stock</p></aside></div></div></template>
<script setup lang="ts">import {computed,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {products} from '../services/mock';const route=useRoute(),router=useRouter(),editing=computed(()=>route.params.id!==undefined);const tabs=['Basic info','Media','Pricing & Inventory'];const tab=ref(tabs[0]);const p=products.find(x=>x.id===route.params.id);const form=reactive({name:p?.name||'',sku:p?.sku||'',category:p?.category||'Lighting',description:'',price:p?.price||0,compareAtPrice:0,stock:p?.stock||0,status:p?.status||'Draft'});const format=(n:number)=>new Intl.NumberFormat('en-EG').format(n);function save(){router.push('/products')}</script>
<style scoped>.head-actions{display:flex;gap:8px}.editor{display:grid;grid-template-columns:1fr 330px;gap:16px}.form-card{padding:0}.tabs{display:flex;border-bottom:1px solid #eee;padding:0 20px}.tabs button{border:0;background:none;padding:15px 14px;color:#777;border-bottom:2px solid transparent}.tabs button.active{color:#111;border-bottom-color:#111}.form{display:grid;gap:17px;padding:24px}.form label{display:grid;gap:7px;font-weight:600;font-size:12px}.form.two{grid-template-columns:1fr 1fr}.media-box{padding:24px}.upload{min-height:300px;border:1px dashed #ccc;border-radius:10px;display:grid;place-items:center;text-align:center;color:#777}.upload span{font-size:11px}.preview{padding:20px;height:max-content}.preview-image{aspect-ratio:1;background:#f0f0ee;border-radius:10px;margin:18px 0}.preview h3{margin:0}.preview p{margin-bottom:0}@media(max-width:950px){.editor{grid-template-columns:1fr}.preview{display:none}}@media(max-width:550px){.form.two{grid-template-columns:1fr}.tabs{overflow:auto}.tabs button{white-space:nowrap}}
</style>
